mapper.select:
SELECT a.inv_aim
FROM BOK_VAL_SCHEME_DETAIL_SPECIAL a
WHERE a.scheme_id = #{schemeId,jdbcType=VARCHAR}
AND a.Finprod_Id = #{finprodid,jdbcType=VARCHAR}
AND #{tradeDate,jdbcType=DATE} >= a.vdate
AND ifnull(a.mdate,STR_TO_DATE('2099-12-31','%Y-%m-%d')) >= #{tradeDate,jdbcType=DATE}
AND LIMIT = 1
